begin;
-- These baseline assertions are transaction-local, even after Education is enabled.
update public.app_settings set generation_paused=true,claims_paused=true where id='global';
update public.app_settings set limits=limits||'{"educationExecutionVerified":false}' where id='global';
set local search_path=public,extensions,pg_temp;
select no_plan();
select ok(not has_function_privilege('anon','public.worker_control(text,integer,text,jsonb)','execute'),'Anonymous worker RPC denied');
select ok(not has_function_privilege('authenticated','public.worker_control(text,integer,text,jsonb)','execute'),'User JWT cannot call worker RPC');
select ok(has_function_privilege('service_role','public.worker_control(text,integer,text,jsonb)','execute'),'Only server authority exposes worker control');
insert into public.workers(id,label,enabled,protocol_version,capabilities) select ('a1500000-0000-4000-8000-00000000000'||n)::uuid,'Worker fixture',true,1,'{"modes":["education"],"orientations":["landscape","portrait"],"schemaVersions":[1],"compositionVersion":"v1"}' from generate_series(1,2)n;
insert into public.worker_credentials(worker_id,token_hash,expires_at) select ('a1500000-0000-4000-8000-00000000000'||n)::uuid,repeat(case when n=1 then 'a' else 'b' end,64),now()+interval '1 hour' from generate_series(1,2)n;
create temporary table wfixture(claim jsonb,heartbeat jsonb,assignment jsonb,second jsonb);
insert into wfixture values('{"instanceId":"a1500000-0000-4000-8000-000000000011","capabilities":{"modes":["education"],"orientations":["landscape","portrait"],"schemaVersions":[1],"compositionVersion":"v1"}}','{"instanceId":"a1500000-0000-4000-8000-000000000011","health":{"freeDiskBytes":"4000000000","freeMemoryBytes":"2000000000","toolVersions":{"node":"24.22.1"}}}',null,null);
select throws_ok($$select public.worker_control(repeat('c',64),1,'claim',(select claim from wfixture))$$,'P1501',null::text,'Unknown credential denied');
select throws_ok($$select public.worker_control(repeat('a',64),2,'claim',(select claim from wfixture))$$,'P1502',null::text,'Protocol mismatch denied');
select throws_ok($$select public.worker_control(repeat('a',64),1,'claim',jsonb_set((select claim from wfixture),'{capabilities,modes}','["software"]'))$$,'P1504',null::text,'Worker cannot upgrade registered modes');
update public.workers set enabled=false where id='a1500000-0000-4000-8000-000000000001';
select throws_ok($$select public.worker_control(repeat('a',64),1,'claim',(select claim from wfixture))$$,'P1501',null::text,'Disabled worker denied');
update public.workers set enabled=true where id='a1500000-0000-4000-8000-000000000001';
update public.worker_credentials set expires_at=now()-interval '1 second',created_at=now()-interval '1 hour' where token_hash=repeat('a',64);
select throws_ok($$select public.worker_control(repeat('a',64),1,'claim',(select claim from wfixture))$$,'P1501',null::text,'Expired credential denied');
update public.worker_credentials set expires_at=now()+interval '1 hour' where token_hash=repeat('a',64);
select is(public.worker_control(repeat('a',64),1,'heartbeat',(select heartbeat from wfixture))->>'claimsPaused','true','Idle heartbeat reflects current pause');
select ok((select last_seen_at is not null from public.workers where id='a1500000-0000-4000-8000-000000000001'),'Heartbeat records real liveness');
select is(public.worker_control(repeat('a',64),1,'claim',(select claim from wfixture))->>'idle','true','Paused claims return no private work');
insert into auth.users(id,email) values('a1500000-0000-4000-8000-000000000021','worker-sql@example.invalid');
insert into public.usage_accounts(scope,owner_id,byte_limit,output_limit) values('user','a1500000-0000-4000-8000-000000000021',400000000,3);
insert into public.projects(id,owner_id,title,mode,draft_input) values('a1500000-0000-4000-8000-000000000022','a1500000-0000-4000-8000-000000000021','Worker assignment','education','{"topic":"Turbines","audience":"beginner","intendedUse":"personal-learning","sources":[]}');
select set_config('request.jwt.claims','{"sub":"a1500000-0000-4000-8000-000000000021","role":"authenticated"}',true);
update public.app_settings set generation_paused=false,claims_paused=false;
update public.app_settings set limits=limits||'{"enabledGenerationModes":[]}';
select throws_ok($$select public.enqueue_generation('a1500000-0000-4000-8000-000000000022','disabled-mode','{"draftVersion":1,"preferences":{"targetSeconds":60,"orientation":"landscape","voiceProfileId":"Kore"},"acknowledgments":{"sourceRights":true,"externalAiProcessing":true,"policyVersion":"v1"}}')$$,'P1402',null::text,'Configured mode allowlist blocks new admission');
update public.app_settings set limits=limits||'{"enabledGenerationModes":["education"]}';
select lives_ok($$select public.enqueue_generation('a1500000-0000-4000-8000-000000000022','worker-fixture','{"draftVersion":1,"preferences":{"targetSeconds":60,"orientation":"landscape","voiceProfileId":"Kore"},"acknowledgments":{"sourceRights":true,"externalAiProcessing":true,"policyVersion":"v1"}}')$$,'Fixture uses real durable enqueue');
update public.app_settings set limits=limits||'{"enabledGenerationModes":[]}';
select lives_ok($$select public.enqueue_generation('a1500000-0000-4000-8000-000000000022','worker-fixture','{"draftVersion":1,"preferences":{"targetSeconds":60,"orientation":"landscape","voiceProfileId":"Kore"},"acknowledgments":{"sourceRights":true,"externalAiProcessing":true,"policyVersion":"v1"}}')$$,'Existing receipt remains recoverable after mode disabling');
update public.app_settings set limits=limits||'{"enabledGenerationModes":["education"]}';
update wfixture set assignment=public.worker_control(repeat('a',64),1,'claim',claim);
select is((select assignment->>'leaseToken' from wfixture),'1','First claim gets fence one');
select is((select status from public.jobs where id=(select (assignment->>'jobId')::uuid from wfixture)),'running','Claim transitions job to running');
select is((select worker_instance_id::text from public.worker_slots where slot_name='processing'),'a1500000-0000-4000-8000-000000000011','Slot binds the actual worker process');
select is((select public.worker_control(repeat('a',64),1,'claim',claim)->>'leaseToken' from wfixture),'1','Lost response recovery returns same fence');
select is((select count(*)::integer from public.job_runs where job_id=(select (assignment->>'jobId')::uuid from wfixture)),1,'Claim recovery creates no second run');
select is((select public.worker_control(repeat('a',64),1,'claim',jsonb_set(claim,'{instanceId}','"a1500000-0000-4000-8000-000000000012"'))->>'idle' from wfixture),'true','Second process cannot recover another instance lease');
select is((select public.worker_control(repeat('b',64),1,'claim',jsonb_set(claim,'{instanceId}','"a1500000-0000-4000-8000-000000000012"'))->>'idle' from wfixture),'true','Second worker cannot occupy global slot');
select throws_ok($$select public.worker_control(repeat('a',64),1,'heartbeat',jsonb_set((select heartbeat from wfixture),'{assignment}','{"jobId":"a1500000-0000-4000-8000-000000000099","leaseToken":"1"}'))$$,'P1503',null::text,'Worker cannot heartbeat an unrelated job');
update wfixture set heartbeat=heartbeat||jsonb_build_object('assignment',jsonb_build_object('jobId',assignment->>'jobId','leaseToken',assignment->>'leaseToken'));
select pg_sleep(0.02);
select lives_ok($$select public.worker_control(repeat('a',64),1,'heartbeat',(select heartbeat from wfixture))$$,'Matching current lease renews');
select ok((select active_ms>0 from public.jobs where id=(select (assignment->>'jobId')::uuid from wfixture)),'Elapsed time is server measured');

create function pg_temp.exec_worker(op jsonb) returns jsonb language sql as $test$
 select public.worker_execute(repeat('a',64),1,jsonb_build_object('instanceId',claim->>'instanceId','health',heartbeat->'health','jobId',assignment->>'jobId','leaseToken',assignment->>'leaseToken','operation',op)) from wfixture;
$test$;
select ok(not has_function_privilege('authenticated','public.worker_execute(text,integer,jsonb)','execute'),'User cannot execute worker mutations');
select lives_ok($test$select pg_temp.exec_worker('{"type":"state"}')$test$,'Worker may restore scoped checkpoint state');
select lives_ok($test$select pg_temp.exec_worker('{"type":"progress","stage":"voice","completedScenes":2,"totalScenes":4}')$test$,'Fenced worker records measured narration progress');
select is((select progress->>'completedScenes' from public.jobs where id=(select (assignment->>'jobId')::uuid from wfixture)),'2','Scene count persisted');
create temporary table progress_sequence as select event_sequence from public.jobs where id=(select (assignment->>'jobId')::uuid from wfixture);
select pg_temp.exec_worker('{"type":"progress","stage":"voice","completedScenes":2,"totalScenes":4}');
select is((select event_sequence from public.jobs where id=(select (assignment->>'jobId')::uuid from wfixture)),(select event_sequence from progress_sequence),'Repeated telemetry adds no duplicate progress event');
select throws_ok($test$select pg_temp.exec_worker('{"type":"progress","stage":"voice","completedScenes":5,"totalScenes":4}')$test$,'P1601',null::text,'Impossible completion counts rejected');
select throws_ok($test$select pg_temp.exec_worker('{"type":"progress","stage":"render","completedScenes":2,"totalScenes":4}')$test$,'P1601',null::text,'Narration counts cannot masquerade as rendered frames');
select throws_ok($test$select pg_temp.exec_worker('{"type":"progress","stage":"voice","completedScenes":2}')$test$,'P1601',null::text,'Partial count pair rejected');
select pg_temp.exec_worker('{"type":"progress","stage":"story"}');
select is((select progress from public.jobs where id=(select (assignment->>'jobId')::uuid from wfixture)),'{"completedScenes":0,"totalScenes":null}'::jsonb,'Automatic story correction clears old narration counts');
create temporary table attempts(first jsonb,second jsonb);
insert into attempts select pg_temp.exec_worker('{"type":"attempt","nonce":"a1600000-0000-4000-8000-000000000001","operationKey":"story","provider":"Gemini","modelId":"fixture","requestHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}'),null;
update attempts set second=pg_temp.exec_worker('{"type":"attempt","nonce":"a1600000-0000-4000-8000-000000000001","operationKey":"story","provider":"Gemini","modelId":"fixture","requestHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}');
select is((select first->'value'->>'dispatchAuthorized' from attempts),'true','Fresh nonce authorizes one provider call');
select is((select second->'value'->>'dispatchAuthorized' from attempts),'false','Replayed nonce never authorizes another provider call');
select is((select provider_attempt_count from public.jobs where id=(select (assignment->>'jobId')::uuid from wfixture)),1,'Dispatch consumes one durable attempt');
select throws_ok($test$select pg_temp.exec_worker('{"type":"attempt","nonce":"a1600000-0000-4000-8000-000000000002","operationKey":"story","provider":"Gemini","modelId":"fixture","requestHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}')$test$,'P1603',null::text,'Unknown prior dispatch must reconcile before repeating');
select lives_ok($test$select pg_temp.exec_worker(jsonb_build_object('type','attempt_result','attemptId',(select first->'value'->>'attemptId' from attempts),'status','succeeded'))$test$,'Dispatch outcome is durable');
select throws_ok($test$select pg_temp.exec_worker(jsonb_build_object('type','attempt_result','attemptId',(select first->'value'->>'attemptId' from attempts),'status','failed'))$test$,'P1602',null::text,'A success cannot be overwritten by a later generic failure');
select lives_ok($test$select pg_temp.exec_worker('{"type":"repair","key":"one","stage":"story","reason":"PLAN_INVALID"}')$test$,'First repair reserved');
select lives_ok($test$select pg_temp.exec_worker('{"type":"repair","key":"one","stage":"story","reason":"PLAN_INVALID"}')$test$,'Repair replay is idempotent');
select lives_ok($test$select pg_temp.exec_worker('{"type":"repair","key":"two","stage":"voice","reason":"DURATION_INVALID"}')$test$,'Second shared repair reserved');
select throws_ok($test$select pg_temp.exec_worker('{"type":"repair","key":"three","stage":"voice","reason":"DURATION_INVALID"}')$test$,'P1603',null::text,'Third repair cannot reset shared budget');
create temporary table allocation(value jsonb);
insert into allocation select pg_temp.exec_worker('{"type":"allocate","key":"audio","kind":"audio","bytes":1000,"checksum":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}');
select is((select used_bytes from public.usage_accounts where owner_id='a1500000-0000-4000-8000-000000000021'),1000::bigint,'Write ceiling charged before any upload permit');
select lives_ok($test$select pg_temp.exec_worker('{"type":"allocate","key":"audio","kind":"audio","bytes":1000,"checksum":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}')$test$,'Allocation replay does not recharge');
select is((select used_bytes from public.usage_accounts where owner_id='a1500000-0000-4000-8000-000000000021'),1000::bigint,'Replayed allocation charged once');
select throws_ok($test$select pg_temp.exec_worker(jsonb_build_object('type','confirm','assetId',(select value->'value'->>'assetId' from allocation)))$test$,'P1605',null::text,'Missing physical bytes cannot be confirmed');
select throws_ok($test$select pg_temp.exec_worker(jsonb_build_object('type','read','assetId',(select value->'value'->>'assetId' from allocation)))$test$,'P1601',null::text,'Unvalidated artifact cannot receive a read permit');
select throws_ok($test$select pg_temp.exec_worker(jsonb_build_object('type','complete','key','complete','video',(select value->'value'->>'assetId' from allocation),'thumbnail',(select value->'value'->>'assetId' from allocation),'srt',(select value->'value'->>'assetId' from allocation),'vtt',(select value->'value'->>'assetId' from allocation),'report',(select value->'value'->>'assetId' from allocation)))$test$,'P1601',null::text,'Incomplete unverified artifacts cannot publish Ready');
select ok(not has_function_privilege('authenticated','public.describe_education_result(uuid,uuid,text)','execute'),'Private object descriptor is server-only');
select is(public.education_execution_available(),false,'Paused/unverified Education never advertises generation');
select is(public.get_education_run('a1500000-0000-4000-8000-000000000022')->>'status','running','Owner can recover the real Education job');
select ok(not (public.get_education_run('a1500000-0000-4000-8000-000000000022') ? 'input'),'Run projection omits private input');
select set_config('request.jwt.claims','{"sub":"a1500000-0000-4000-8000-000000000099","role":"authenticated"}',true);
select throws_ok($test$select public.get_education_run('a1500000-0000-4000-8000-000000000022')$test$,'42501',null::text,'Foreign user cannot inspect an Education run');
select set_config('request.jwt.claims','{"sub":"a1500000-0000-4000-8000-000000000021","role":"authenticated"}',true);
-- Three persisted attempts per logical operation survive all same-job retries.
do $budget$ declare n integer;v jsonb;begin for n in 1..3 loop
 v:=pg_temp.exec_worker(jsonb_build_object('type','attempt','nonce',gen_random_uuid(),'operationKey','transient-unit','provider','Gemini','modelId','fixture','requestHash',repeat('b',64)));
 perform pg_temp.exec_worker(jsonb_build_object('type','attempt_result','attemptId',v->'value'->>'attemptId','status','failed'));
end loop;end $budget$;
select throws_ok($test$select pg_temp.exec_worker(jsonb_build_object('type','attempt','nonce',gen_random_uuid(),'operationKey','transient-unit','provider','Gemini','modelId','fixture','requestHash',repeat('b',64)))$test$,'P1603',null::text,'Fourth call to the same logical operation is denied');
update public.jobs set provider_attempt_count=23 where owner_id='a1500000-0000-4000-8000-000000000021';
select throws_ok($test$select pg_temp.exec_worker('{"type":"attempt","nonce":"a1600000-0000-4000-8000-000000000003","operationKey":"another","provider":"Gemini","modelId":"fixture","requestHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}')$test$,'P1603',null::text,'Stricter dispatch ceiling preserves the original 24-call lease safeguard');
select lives_ok($test$select pg_temp.exec_worker('{"type":"progress","stage":"render"}')$test$,'Finalization can proceed without spending another provider attempt');
select lives_ok($test$select pg_temp.exec_worker('{"type":"fail","code":"PIPELINE_FAILED"}')$test$,'Fenced failure terminates the job');
select is((select reserved_bytes from public.usage_accounts where owner_id='a1500000-0000-4000-8000-000000000021'),0::bigint,'Failure releases only unused reservation');
select is((select used_bytes from public.usage_accounts where owner_id='a1500000-0000-4000-8000-000000000021'),1000::bigint,'Failure retains physical/late-upload ceiling until actual cleanup');
select * from finish();rollback;
